//! Decision trees for text normalisation, from ceplang_en.dll.
//!
//! Generated by `python _out/gen_carts.py`; do not edit. `us_nums`
//! (@0xa7ba8) decides how a run of digits is read and `us_phrasing`
//! (@0xab0b0) decides where a phrase break falls. Both are flite's own
//! trees -- the constants match `us_nums_cart.c` exactly -- but they are
//! taken from the DLL rather than transcribed, so a voice pack that ships
//! a different one can be regenerated.
//!
//! `op` 0 is a string equality test, 2 is `<` on the feature read as a
//! number, and 255 marks a leaf whose `sval` is the answer. "Yes" is
//! always the next node; "no" jumps to `no`.

pub struct Node {
    pub feat: u8,
    pub op: u8,
    pub no: u16,
    pub sval: &'static str,
    pub fval: f32,
}

